import mongoose from 'mongoose';
import { CUSTOMER_STATUS } from '../constants/index.js';
import { jsonOptions } from './shared/json.js';

const { ObjectId } = mongoose.Schema.Types;

// A company we sell to. Deliberately thin: the name, address, tax numbers,
// contacts and everything else stay on the Company and are read from there,
// never copied. This record holds only what is specific to being a customer.
const customerSchema = new mongoose.Schema(
  {
    // Generated by the server; never accepted from clients.
    customerNumber: { type: String, required: true, unique: true, immutable: true },
    // One customer per company.
    companyId: { type: ObjectId, ref: 'Company', required: true, unique: true, immutable: true },
    // The main person to deal with; must work at the company.
    primaryContactId: { type: ObjectId, ref: 'Contact' },
    // The user who looks after the account.
    accountManagerId: { type: ObjectId, ref: 'User', index: true },
    status: { type: String, enum: Object.values(CUSTOMER_STATUS), default: CUSTOMER_STATUS.ACTIVE, index: true },
    // When the company became a customer: its first order's date, or the day it was added.
    customerSince: { type: Date, required: true, index: true },
    // The order that made it a customer, when there was one.
    firstOrderId: { type: ObjectId, ref: 'Order' },
    notes: { type: String, trim: true, maxlength: 5000 },
    createdBy: { type: ObjectId, ref: 'User' },
  },
  {
    timestamps: true,
    toJSON: jsonOptions({
      aliases: {
        companyId: 'company',
        primaryContactId: 'primaryContact',
        accountManagerId: 'accountManager',
        firstOrderId: 'firstOrder',
        createdBy: 'createdByUser',
      },
    }),
  }
);

export default mongoose.model('Customer', customerSchema);
